-- Run once in the AI-QR Supabase SQL editor. No student authentication required.
-- Scores/categories are generated by PostgreSQL, never trusted from the browser.
create table public.ai_study_profile_responses (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  q1 smallint not null check (q1 between 1 and 4),
  q2 smallint not null check (q2 between 1 and 4),
  q3 smallint not null check (q3 between 1 and 4),
  q4 smallint not null check (q4 between 1 and 4),
  q5 smallint not null check (q5 between 1 and 4),
  total_score smallint generated always as (q1 + q2 + q3 + q4 + q5) stored not null,
  profile_category text generated always as (
    case when q1+q2+q3+q4+q5 >= 17 then 'AI Study Strategist'
         when q1+q2+q3+q4+q5 >= 13 then 'AI Explorer'
         when q1+q2+q3+q4+q5 >= 9 then 'AI Shortcut Surfer'
         else 'AI Rookie' end
  ) stored not null,
  program_area text check (program_area is null or program_area in (
    'Elementary Education', 'Mathematics Education', 'Science Education',
    'Social Science Education', 'Physical Education', 'Health, Leisure & Fitness',
    'Other / Undecided'
  ))
);
alter table public.ai_study_profile_responses enable row level security;
revoke all on public.ai_study_profile_responses from public, anon, authenticated;
grant usage on schema public to anon, authenticated;
grant insert (id, q1, q2, q3, q4, q5, program_area)
  on public.ai_study_profile_responses to anon, authenticated;
create policy "Anonymous assessment submissions only"
  on public.ai_study_profile_responses for insert to anon, authenticated
  with check (true);
-- There are deliberately no SELECT, UPDATE, or DELETE policies or browser grants.

create schema if not exists ai_study_private;
revoke all on schema ai_study_private from public, anon, authenticated;
grant usage on schema ai_study_private to authenticated;
create table ai_study_private.instructors (
  user_id uuid primary key references auth.users(id) on delete cascade
);
alter table ai_study_private.instructors enable row level security;
revoke all on ai_study_private.instructors from public, anon, authenticated;

-- The privileged aggregation runs in a private schema, checks a live allowlist,
-- and returns only aggregate values. No IDs, timestamps, or raw answers returned.
create function ai_study_private.summary()
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare result jsonb;
begin
  if auth.uid() is null or not exists (
    select 1 from ai_study_private.instructors where user_id = auth.uid()
  ) then
    raise exception 'Instructor access required' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'total_responses', count(*),
    'average_score', round(avg(total_score), 2),
    'question_averages', jsonb_build_array(round(avg(q1),2), round(avg(q2),2), round(avg(q3),2), round(avg(q4),2), round(avg(q5),2)),
    'profiles', (select coalesce(jsonb_agg(jsonb_build_object('category', profile_category, 'count', n)), '[]'::jsonb)
      from (select profile_category, count(*) n from public.ai_study_profile_responses group by profile_category) p),
    'programs', (select coalesce(jsonb_agg(jsonb_build_object(
      'program_area', g.area, 'count', g.n, 'average_score', g.mean,
      'profiles', (select coalesce(jsonb_agg(jsonb_build_object('category', s.profile_category, 'count', s.n)), '[]'::jsonb)
        from (select profile_category, count(*) n from public.ai_study_profile_responses
          where coalesce(program_area, 'Not provided') = g.area group by profile_category) s)
    ) order by g.area), '[]'::jsonb)
      from (select coalesce(program_area, 'Not provided') area, count(*) n, round(avg(total_score),2) mean
        from public.ai_study_profile_responses group by coalesce(program_area, 'Not provided')) g)
  ) into result from public.ai_study_profile_responses;
  return result;
end;
$$;
revoke all on function ai_study_private.summary() from public, anon, authenticated;
grant execute on function ai_study_private.summary() to authenticated;

-- Public API wrapper is SECURITY INVOKER, not SECURITY DEFINER.
create function public.ai_study_profile_summary()
returns jsonb language sql security invoker set search_path = ''
as $$ select ai_study_private.summary(); $$;
revoke all on function public.ai_study_profile_summary() from public, anon, authenticated;
grant execute on function public.ai_study_profile_summary() to authenticated;

notify pgrst, 'reload schema';
